<template><main class="page-width detail-page"><router-link to="/shop" class="back">← Back to shop</router-link><div v-if="product" class="detail"><div class="detail-image"><img :src="product.image" :alt="product.name"></div><div class="detail-copy"><span class="eyebrow">A GOOD FIND</span><h1>{{ product.name }}</h1><p class="category">{{ store.getCategoryById(product.category)?.name }}</p><div class="price">${{ product.price.toFixed(2) }}</div><p>{{ product.description || 'A hand-picked favourite for your everyday shop. Add it to your basket and make your next meal a little more special.' }}</p><div class="detail-actions"><button @click="store.addToCart(product)">Add to basket <Icon icon="mdi:shopping-outline"/></button><button class="heart" @click="store.toggleWishlist(product)"><Icon :icon="store.isWishlisted(product.id)?'mdi:heart':'mdi:heart-outline'"/></button></div><div class="detail-points"><span><Icon icon="mdi:truck-fast-outline"/> Convenient delivery</span><span><Icon icon="mdi:shield-check-outline"/> Secure checkout</span></div></div></div><div v-else class="empty">We couldn't find that product. <router-link to="/shop">Browse all products</router-link></div></main></template>
<script setup>
import { computed, watchEffect } from 'vue'
import { useRoute } from 'vue-router'
import { useAllProductStore } from '@/stores/useAllProductStore'
const route=useRoute(),store=useAllProductStore()
const product=computed(()=>store.allProductList.find(item=>String(item.id)===String(route.params.id)))
watchEffect(()=>{if(product.value)store.addRecentlyViewed(product.value)})
</script>
<style scoped>.detail-page{padding:35px 0 80px;min-height:60vh}.back{font-size:11px;color:#47734b;font-weight:700}.detail{display:grid;grid-template-columns:1fr 1fr;gap:55px;align-items:center;margin-top:25px}.detail-image{background:#f5f7f1;border-radius:12px;min-height:390px;display:grid;place-items:center;padding:35px}.detail-image img{width:100%;height:320px;object-fit:contain;mix-blend-mode:multiply}.eyebrow{font-size:9px;letter-spacing:1.6px;color:#a87937;font-weight:800}.detail-copy h1{font-size:35px;color:#263d2d;margin:10px 0 4px}.category{font-size:11px;color:#899289}.price{font-size:24px;font-weight:800;color:#47734b;margin:20px 0}.detail-copy>p:last-of-type{font-size:13px;line-height:1.8;color:#849084;max-width:420px}.detail-actions{display:flex;gap:10px;margin:25px 0}.detail-actions button{display:flex;align-items:center;justify-content:center;gap:9px;border:0;background:#24462f;color:#fff;border-radius:5px;padding:13px 20px;font-size:11px;font-weight:700;cursor:pointer}.detail-actions .heart{background:#f0f4ed;color:#47734b;padding:13px}.detail-points{display:flex;gap:20px;flex-wrap:wrap}.detail-points span{display:flex;align-items:center;gap:6px;font-size:10px;color:#748174}.empty{padding:40px}@media(max-width:700px){.detail{grid-template-columns:1fr;gap:25px}.detail-image{min-height:260px}.detail-image img{height:220px}.detail-copy h1{font-size:28px}}</style>